package encryption

import (
	"encoding/hex"

	"github.com/tink-crypto/tink-go/v2/streamingaead/subtle"
	"github.com/transferia/transferia/library/go/core/xerrors"
	"github.com/transferia/transferia/pkg/abstract/model"
)

// KeySize is the size of a user key in bytes. Users pass it hex-encoded (64 characters), like a password,
// for example generated by `openssl rand -hex 32`. pkg/cipher keys use the same encoding.
const KeySize = 32

// Key is a user key for client-side encryption of S3 objects.
// Every object is encrypted with its own key derived from Key and a random per-object salt.
type Key struct {
	material []byte
}

// ParseKey decodes a hex-encoded 256-bit key. An empty value means that encryption is disabled: (nil, nil) is returned.
// Errors never contain the key itself, because they end up in logs and user-visible messages.
func ParseKey(raw model.SecretString) (*Key, error) {
	if raw == "" {
		return nil, nil
	}
	if len(raw) != hex.EncodedLen(KeySize) {
		return nil, xerrors.Errorf("encryption key must be %d hex characters (%d bytes), got %d characters", hex.EncodedLen(KeySize), KeySize, len(raw))
	}
	material, err := hex.DecodeString(string(raw))
	if err != nil {
		return nil, xerrors.New("encryption key must contain only hex characters 0-9, a-f")
	}
	return &Key{material: material}, nil
}

// String hides the key material from fmt and loggers.
func (k Key) String() string {
	return "***HIDDEN***"
}

// GoString hides the key material from %#v.
func (k Key) GoString() string {
	return k.String()
}

func (k *Key) streamingAEAD() (*subtle.AESGCMHKDF, error) {
	streamingAEAD, err := subtle.NewAESGCMHKDF(k.material, hkdfHash, derivedKeySize, ciphertextSegmentSize, 0)
	if err != nil {
		return nil, xerrors.Errorf("unable to create streaming AEAD: %w", err)
	}
	return streamingAEAD, nil
}
